SELECT * FROM memory_summaries
WHERE user_id = #{userId} AND deleted = 0 AND status != 'STALE'
  AND tag_id IN

      #{tid}

  AND (


          project_id IS NULL OR project_id IN

              #{pid}



          project_id IS NULL




                  project_id IN

                      #{pid}


              1 = 0



  )
  AND summarized_at >= NOW() - make_interval(days => #{relativeDays})
  AND summarized_at >= #{twStart}
  AND summarized_at <= #{twEnd}
ORDER BY summarized_at DESC

